cat >> src/chat_input.rs <<'EOF'

#[cfg(test)]
mod chain_probe {
    use gpui_kit::component::Root;
    use gpui_kit::test::TestWindowExt as _;
    use gpui_kit::{AppContext as _, TestAppContext};

    use super::ChatInput;

    #[gpui_kit::test]
    fn probe_chain_edges(cx: &mut TestAppContext) {
        cx.update(|cx| {
            gpui_kit::init(cx);
            crate::theme::init(cx);
            gpui_kit::component::Theme::change(gpui_kit::component::ThemeMode::Dark, None, cx);
            super::bind_keys(cx);
            crate::piton_syntax::init();
            crate::project_directory::ProjectDirectory::init(cx);
        });
        let mut input = None;
        let window = cx.add_window(|window, cx| {
            let view = cx.new(|cx| ChatInput::new(window, cx));
            input = Some(view.clone());
            Root::new(view, window, cx)
        });
        let input = input.unwrap();
        let handle: gpui_kit::AnyWindowHandle = window.into();
        for scale in [2.0f32, 1.25] {
            cx.simulate_window_scale_factor_change(handle, scale);
            for tab in [1usize, 0, 2, 3] {
                cx.update_window(handle, |_, window, cx| {
                    input.update(cx, |input, cx| input.select_tab(tab, window, cx));
                })
                .unwrap();
                for _ in 0..40 {
                    std::thread::sleep(std::time::Duration::from_millis(25));
                    cx.update_window(handle, |_, window, cx| window.render_frame(cx)).unwrap();
                }
                cx.update_window(handle, |_, window, cx| {
                    window.render_frame(cx);
                    crate::frame_image::save(window, std::path::Path::new(&format!("/tmp/chain-{scale}-{tab}.ppm")));
                })
                .unwrap();
            }
        }
    }
}
EOF
