python3 - <<'EOF'
p='/home/hyphyphyph/piton/repl/src/chat_input.rs'
s=open(p).read()
old="""                    let (x, y) = ((left + right) / 2. * scale, bottom * scale - 0.5);
                    window.painted_quads().into_iter().any(|q| {"""
new="""                    let (x, y) = ((left + right) / 2. * scale, bottom * scale - 0.5);
                    let quads = window.painted_quads();
                    // Whether an opaque quad drawn after `order` covers the point.
                    let covered = |order| {
                        quads.iter().any(|q| {
                            let (b, m) = (&q.bounds, &q.content_mask.bounds);
                            q.order > order
                                && q.background.as_solid().is_some_and(|c| c.a >= 0.99)
                                && x >= b.origin.x.0.max(m.origin.x.0)
                                && x < (b.origin.x.0 + b.size.width.0).min(m.origin.x.0 + m.size.width.0)
                                && y >= b.origin.y.0.max(m.origin.y.0)
                                && y < (b.origin.y.0 + b.size.height.0).min(m.origin.y.0 + m.size.height.0)
                        })
                    };
                    quads.iter().any(|q| {"""
assert s.count(old)==1; s=s.replace(old,new)
old="""                        border && visible(x, y)
                    })"""
new="""                        border && visible(x, y) && !covered(q.order)
                    })"""
assert s.count(old)==1; s=s.replace(old,new)
open(p,'w').write(s)
EOF
